<#
    Installer-identity PR 3 (spec 2.4, 2.8, 2.12; D12, D20, D21, D24, L3, L28, L33, L39, SV5): Set-Win32ToolkitPriorInstall,
    the 17th export.

      [1] metadata: ConfirmImpact High, DefaultParameterSetName List, -Mode mandatory (no default) in every add / mode set,
          exported by the manifest (17 functions); the parameter-set resolution matrix (every documented call line
          resolves to its set); the source file is ASCII-only (the preview writes '<=').
      [2] List writes nothing; -WhatIf writes nothing and prints the preview with the device consequence.
      [3] refusals before anything is written: a script without the remove-prior blocks, PriorCheckFirst false or another
          catalog revision -> W32T.PriorInstallSlotsMissing; a manual app that is not completed (NotConfigured.json) ->
          W32T.PriorInstallRefused; any rule (Block too) before the install capture ->
          W32T.PriorInstallRefused; an invalid rule -> W32T.PriorInstallInvalid naming every failed rule; -Id with two
          values in an add set, -DisplayName with -DisplayNameTemplate, no name without a DISPLAYNAME waiver -> errors.
      [4] Manual writes: the rule, AddedOn, D20 (ProcessesToClose union, sorted; -Remove keeps the names); every other
          AppConfig section byte-identical; SetMode Block -> Enforce changes only the mode (and sets it on a hand-edited
          rule without one); the 'Prove it' next step.
      [5] FromUpdateTest: the High candidate, -CandidateKey another, VersionMin = the observed version (exact),
          VersionMax = the observed version for a package of the same family (an EXE package) and the package version
          otherwise, -VersionMax overrides; a Windows Installer candidate is never written; hostile candidate strings are
          neutralised in the preview.
      [6] capture lineage (rules written by hand): Manual / FromUpdateTest over its id or tuple refused; -Waive PROOF on it
          refused; SetMode -Mode Enforce refused with the exact -FromSiblingCapture command.
      [7] decisions: one record per Kind + Code + Target (a newer one replaces it); -Revoke removes a waiver but never an
          Approval; a DISPLAYNAME waiver declared first allows an empty name.
      [8] FromSiblingCapture (PR 3b, A1; records from Tests\Fixtures\sibling-proposal): Enforce without -ProposalId refused;
          one confirmation and one Approval per proposal; an ineligible proposal is never written; the bulk Block writes only
          High flag-free proposals whose identity is not a rule yet (a carried Enforce rule stays Enforce); a Manual rule with
          a proposal's identity (a relabel) is refused; List shows the proposals; SetMode Enforce on a captured rule whose
          id is not its proposal's names the proposal (found by identity) in the refused command.

    Projects are generated under %TEMP% from the PSADT 4.1.8 golden with the real generator. Run:  pwsh -File Tests\PriorInstall.unit.ps1
#>
[Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseShouldProcessForStateChangingFunctions', '', Justification = 'test fixture builders')]
[Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSAvoidOverwritingBuiltInCmdlets', '', Justification = 'a test shadow of Get-AuthenticodeSignature (the capture fixtures carry no real signature)')]
[CmdletBinding()]
param()

$ErrorActionPreference = 'Stop'
$repo = Split-Path -Parent $PSScriptRoot
$fail = 0
function Ok($m)  { Write-Host "  PASS: $m" -ForegroundColor Green }
function Bad($m) { Write-Host "  FAIL: $m" -ForegroundColor Red; $script:fail++ }

Get-ChildItem (Join-Path $repo 'Private') -Filter *.ps1 | ForEach-Object { . $_.FullName }
. (Join-Path $repo 'Public\Set-Win32ToolkitPriorInstall.ps1')
$script:PsadtSupportedRange = [pscustomobject]@{ Min = [version]'4.1.0'; MaxExclusive = [version]'4.3.0'; Display = '4.1.x and 4.2.x' }

$root = Join-Path ([IO.Path]::GetTempPath()) ('w32pi_' + [guid]::NewGuid().ToString('N').Substring(0, 8))
$utf8 = [Text.UTF8Encoding]::new($false)
$PC = '{5C6F8543-7EA8-40B9-B78F-04C78300DE7F}'
$golden = ([IO.File]::ReadAllText((Join-Path $repo 'Tests\Fixtures\psadt-4.1.8\Invoke-AppDeployToolkit.ps1'), [Text.Encoding]::UTF8))

# A project generated by this version: the remove-prior pair + the org dialogs (PriorCheckFirst), an MSI package.
function New-PiProject([string]$Name, [switch]$NoOwn, [switch]$NoOrgUi, [switch]$NoBlocks, [string]$InstallerType = 'msi', [string]$Version = '8.9.9') {
    $p = Join-Path $root $Name
    foreach ($d in 'SupportFiles', 'Documentation', 'Files') { $null = New-Item -ItemType Directory -Path (Join-Path $p $d) -Force }
    $script = Join-Path $p 'Invoke-AppDeployToolkit.ps1'
    [IO.File]::WriteAllText($script, $golden, [Text.UTF8Encoding]::new($true))
    $null = Set-PSADTDataDrivenScript -ScriptPath $script -WarningAction SilentlyContinue
    $t = [IO.File]::ReadAllText($script, [Text.Encoding]::UTF8)
    if (-not $NoOrgUi) {
        $t = Remove-Win32ToolkitPhaseDefaultUi -Content $t -Phase 'Pre-Install'
        $t = Set-Win32ToolkitPhaseBlock -Content $t -Phase 'Pre-Install' -Slot 'org-ui' -Code (Get-Win32ToolkitDeployScriptBlock -Name OrgUiPreInstall)
    }
    if ($NoBlocks) { $t = Remove-Win32ToolkitPhaseBlock -Content (Remove-Win32ToolkitPhaseBlock -Content $t -Phase 'Pre-Install' -Slot 'prior-check') -Phase 'Pre-Install' -Slot 'remove-prior' }
    [IO.File]::WriteAllText($script, $t, [Text.UTF8Encoding]::new($true))
    $cfg = [ordered]@{ SchemaVersion = '1.0'; App = [ordered]@{ Vendor = 'Notepad++ Team'; Name = ''; DisplayName = 'Notepad++'; Version = $Version; Arch = 'x64'; ScriptAuthor = 'Contoso IT' }
        Installer = [ordered]@{ Type = $InstallerType; FileName = 'npp.msi'; SilentArgs = '' }; ProcessesToClose = @('zeta'); Source = [ordered]@{ SchemaVersion = '1.0'; ProductCode = $PC } }
    if (-not $NoOwn) { $cfg['OwnIdentity'] = [ordered]@{ SchemaVersion = '1.0'; ProductCode = $PC; UpgradeCode = ''; ArpKeys = @([ordered]@{ Key = $PC; View = 'Native' }); CapturedOn = '2026-10-25' } }
    [IO.File]::WriteAllText((Join-Path $p 'SupportFiles\AppConfig.json'), ($cfg | ConvertTo-Json -Depth 8), $utf8)
    $p
}
function Get-Cfg([string]$P) { Get-Content -LiteralPath (Join-Path $P 'SupportFiles\AppConfig.json') -Raw | ConvertFrom-Json }
function Get-Hash([string]$P) { (Get-ChildItem -LiteralPath $P -File -Recurse | Sort-Object FullName | ForEach-Object { $_.FullName + '=' + (Get-FileHash -LiteralPath $_.FullName).Hash }) -join ';' }
function Get-Thrown([scriptblock]$A) { try { $null = & $A; '' } catch { $_.FullyQualifiedErrorId + '|' + $_.Exception.Message } }
$manual = @{ Mode = 'Block'; Key = 'Notepad++'; View = 'Native'; Publisher = 'Notepad++ Team'; DisplayName = 'Notepad++ (64-bit x64)'; VersionMin = '8.7.9'; VersionMax = '8.9.8.1'; ProcessName = @('notepad++'); Confirm = $false }
$enforceArgs = @{ UninstallerType = 'nullsoft'; UninstallerFileName = 'uninstall.exe'; InstallDir = '%ProgramFiles%\Notepad++'; MainExe = 'notepad++.exe' }

try {
    # == [1] metadata ======================================================================================
    Write-Host '[1] metadata and parameter sets' -ForegroundColor Cyan
    $cmd = Get-Command Set-Win32ToolkitPriorInstall
    $ast = [Management.Automation.Language.Parser]::ParseFile((Join-Path $repo 'Public\Set-Win32ToolkitPriorInstall.ps1'), [ref]$null, [ref]$null)
    $cb = $ast.Find({ param($n) $n -is [Management.Automation.Language.AttributeAst] -and $n.TypeName.Name -eq 'CmdletBinding' }, $true)
    $named = @{}; foreach ($a in $cb.NamedArguments) { $named[$a.ArgumentName] = $a.Argument.Extent.Text }
    if ($named['ConfirmImpact'] -eq "'High'" -and $named['DefaultParameterSetName'] -eq "'List'" -and $named.ContainsKey('SupportsShouldProcess')) { Ok 'CmdletBinding: SupportsShouldProcess, ConfirmImpact High, DefaultParameterSetName List' } else { Bad "CmdletBinding: $($cb.Extent.Text)" }
    $modeSets = @('Manual', 'FromUpdateTest', 'FromSiblingCapture', 'SetMode') | Where-Object { -not ($cmd.ParameterSets | Where-Object Name -eq $_).Parameters.Where({ $_.Name -eq 'Mode' })[0].IsMandatory }
    if (@($modeSets).Count -eq 0 -and -not $cmd.ScriptBlock.Ast.Body.ParamBlock.Parameters.Where({ $_.Name.VariablePath.UserPath -eq 'Mode' })[0].DefaultValue) { Ok '-Mode is mandatory in Manual, FromUpdateTest, FromSiblingCapture and SetMode, with no default (D24)' } else { Bad "Mode not mandatory in: $($modeSets -join ',')" }
    $psd1 = Import-PowerShellDataFile (Join-Path $repo 'win32-toolkit.psd1')
    if (@($psd1.FunctionsToExport).Count -eq 17 -and @($psd1.FunctionsToExport) -contains 'Set-Win32ToolkitPriorInstall') { Ok 'the manifest exports 17 functions, Set-Win32ToolkitPriorInstall among them' } else { Bad "exports: $(@($psd1.FunctionsToExport).Count)" }
    if (@([IO.File]::ReadAllBytes((Join-Path $repo 'Public\Set-Win32ToolkitPriorInstall.ps1')) | Where-Object { $_ -gt 127 }).Count -eq 0) { Ok 'the source file is ASCII-only' } else { Bad 'non-ASCII bytes in the command' }
    $px = Join-Path $root 'none'
    $calls = @(
        @{ Set = 'List'; Args = @{} }
        @{ Set = 'Manual'; Args = @{ Mode = 'Block'; Key = 'k'; View = 'Native'; Publisher = 'p'; DisplayName = 'd'; VersionMin = '1'; VersionMax = '2' } }
        @{ Set = 'Manual'; Args = @{ Mode = 'Enforce'; Key = 'k'; View = 'Native'; Publisher = 'p'; DisplayNameTemplate = 'd {v}'; VersionMin = '1'; VersionMax = '2'; Id = 'a'; UninstallerType = 'inno' } }
        @{ Set = 'FromUpdateTest'; Args = @{ FromUpdateTest = $true; Mode = 'Block' } }
        @{ Set = 'FromUpdateTest'; Args = @{ FromUpdateTest = $true; Mode = 'Enforce'; CandidateKey = 'k'; VersionMax = '3'; Id = 'a' } }
        @{ Set = 'FromSiblingCapture'; Args = @{ FromSiblingCapture = $true; Mode = 'Block' } }
        @{ Set = 'FromSiblingCapture'; Args = @{ FromSiblingCapture = $true; Mode = 'Enforce'; ProposalId = 'nsis-x64', 'inno-x64' } }
        @{ Set = 'SetMode'; Args = @{ Id = 'a'; Mode = 'Enforce' } }
        @{ Set = 'Remove'; Args = @{ Remove = 'a' } }
        @{ Set = 'Waive'; Args = @{ Waive = 'PROOF'; Target = 'a'; Reason = 'r' } }
        @{ Set = 'Acknowledge'; Args = @{ Acknowledge = 'DATA-LOSS'; Target = 'a'; Reason = 'r' } }
        @{ Set = 'Revoke'; Args = @{ Revoke = 'PROOF'; Target = 'a' } }
    )
    foreach ($c in $calls) {
        $a = $c.Args
        $v = @(try { Set-Win32ToolkitPriorInstall -ProjectPath $px @a -Verbose 4>&1 2>$null 6>$null } catch { $null = $_ }) | Where-Object { $_ -is [Management.Automation.VerboseRecord] } | ForEach-Object { "$_" }
        if (@($v) -contains "Set-Win32ToolkitPriorInstall: parameter set $($c.Set)") { Ok "$(@($a.Keys | Sort-Object) -join ',') -> parameter set $($c.Set)" } else { Bad "$($c.Set): $(@($v) -join ' | ')" }
    }

    # == [2] List / WhatIf ==================================================================================
    Write-Host '[2] List and -WhatIf write nothing' -ForegroundColor Cyan
    $p = New-PiProject 'list'
    $h0 = Get-Hash $p
    $l = @(Set-Win32ToolkitPriorInstall -ProjectPath $p 6>$null)
    if ($l.Count -eq 0 -and (Get-Hash $p) -ceq $h0) { Ok 'List on a project without rules: nothing, nothing written' } else { Bad 'list' }
    # Live rows RC2-BUILD, OP-BLOCK (round 2): the List of a current project with no rule printed nothing, also with the Update
    # test's candidate waiting. One line, then the candidate and its declare command.
    $pl = New-PiProject 'list-cand'
    [IO.File]::WriteAllText((Join-Path $pl 'Documentation\PriorInstallCandidates.json'), (ConvertTo-Json -InputObject ([ordered]@{ SchemaVersion = '1.0'; Baseline = [ordered]@{ Version = '8.8.9'; InstallerType = 'nullsoft'; Family = 'exe' }
                Candidates = @([ordered]@{ ProposedId = 'nsis-x64'; Confidence = 'High'; Key = 'Notepad++'; View = 'Native'; Publisher = 'Notepad++ Team'; ObservedVersion = '8.8.9'; WindowsInstaller = $false }) }) -Depth 5), $utf8)
    $hl = Get-Hash $pl
    $lo = @(Set-Win32ToolkitPriorInstall -ProjectPath $pl 6>&1)
    $li = @($lo | Where-Object { $_ -is [System.Management.Automation.InformationRecord] } | ForEach-Object { "$_" })
    if (@($lo | Where-Object { $_ -isnot [System.Management.Automation.InformationRecord] }).Count -eq 0 -and $li.Count -eq 2 -and $li[0] -ceq 'No prior-install rules in this project.' -and
        $li[1] -ceq "The last Update test left the prior-install candidate nsis-x64 (High) - Notepad++ [Native] 8.8.9, publisher Notepad++ Team. Declare it (Block first): Set-Win32ToolkitPriorInstall -ProjectPath '$pl' -FromUpdateTest -Mode Block" -and (Get-Hash $pl) -ceq $hl) {
        Ok 'List of a current project with no rule: "No prior-install rules in this project." and the waiting candidate with its declare command (no objects, nothing written)'
    } else { Bad "list candidate: $($li -join ' | ')" }
    $out = @(Set-Win32ToolkitPriorInstall -ProjectPath $p @manual @enforceArgs -Mode Enforce -WhatIf 6>&1 | ForEach-Object { "$_" })
    if ((Get-Hash $p) -ceq $h0 -and ($out -join "`n") -match 'Device consequence  : On devices with HKLM\\SOFTWARE\\\.\.\.\\Uninstall\\Notepad\+\+ \(publisher Notepad\+\+ Team, 8\.7\.9 <= version <= 8\.9\.8\.1\) the package runs uninstall\.exe /S _\?=<folder> in %ProgramFiles%\\Notepad\+\+ before it installs') {
        Ok '-WhatIf: the preview and the device consequence printed, nothing written'
    } else { Bad "whatif: $($out -join ' | ')" }

    # == [3] refusals =======================================================================================
    Write-Host '[3] refusals before anything is written' -ForegroundColor Cyan
    foreach ($c in @(@{ L = 'no remove-prior blocks (created before PR 3)'; P = @{ NoBlocks = $true } }, @{ L = 'no org dialogs (PriorCheckFirst false)'; P = @{ NoOrgUi = $true } })) {
        $pp = $c.P
        $q = New-PiProject ([guid]::NewGuid().ToString('N').Substring(0, 6)) @pp
        $h = Get-Hash $q
        $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $q @manual }
        if ($r -like 'W32T.PriorInstallSlotsMissing|*Re-create the project*' -and (Get-Hash $q) -ceq $h) { Ok "$($c.L) -> W32T.PriorInstallSlotsMissing (re-create), nothing written" } else { Bad "$($c.L): $r" }
        # Live row LIVE-PREP: the List of a project created before PR 3 printed nothing at all.
        if ($c.P.ContainsKey('NoBlocks')) {
            $listOld = @(Set-Win32ToolkitPriorInstall -ProjectPath $q 6>&1)
            $hint = @($listOld | Where-Object { $_ -is [System.Management.Automation.InformationRecord] -and "$_" -match 'created before this win32-toolkit version .* re-create it to declare one' })
            if ($hint.Count -eq 1 -and @($listOld | Where-Object { $_ -isnot [System.Management.Automation.InformationRecord] }).Count -eq 0) { Ok 'the List of a project without remove-prior blocks says it must be re-created (no objects)' } else { Bad "old list: $(@($listOld | ForEach-Object { "$_" }) -join ' | ')" }
        }
    }
    $q = New-PiProject 'rev'
    $realBlock = ${function:Get-Win32ToolkitDeployScriptBlock}
    $curRev = [int](& $realBlock -Name RemovePriorRevision)
    function Get-Win32ToolkitDeployScriptBlock { param([string]$Name, $Phase, $HookFile, $FailureAction) if ($Name -eq 'RemovePriorRevision') { return ($curRev + 1) }; & $realBlock @PSBoundParameters }
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $q @manual }
    ${function:Get-Win32ToolkitDeployScriptBlock} = $realBlock
    if ($r -like "W32T.PriorInstallSlotsMissing|*catalog revision $curRev, this version writes revision $($curRev + 1)*") { Ok 'blocks of another catalog revision -> W32T.PriorInstallSlotsMissing' } else { Bad "revision: $r" }
    $q = New-PiProject 'notconfigured'
    [IO.File]::WriteAllText((Join-Path $q 'Documentation\NotConfigured.json'), '{}', $utf8)
    $h = Get-Hash $q
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $q @manual }
    $r2 = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $q -Waive PROOF -Target 'exe-x64' -Reason 'pilot' -Confirm:$false }
    if ($r -like 'W32T.PriorInstallRefused|*NotConfigured.json*' -and $r2 -like 'W32T.PriorInstallRefused|*' -and (Get-Hash $q) -ceq $h) { Ok 'a manual app that is not completed (Documentation\NotConfigured.json) -> W32T.PriorInstallRefused for a rule and a decision, nothing written' } else { Bad "notconfigured: $r / $r2" }
    $q = New-PiProject 'noown' -NoOwn
    $h = Get-Hash $q
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $q @manual }
    if ($r -like 'W32T.PriorInstallRefused|*own uninstall identity is not known*' -and (Get-Hash $q) -ceq $h) { Ok 'a Block rule before the install capture (no own identity) -> W32T.PriorInstallRefused, nothing written (L28)' } else { Bad "noown: $r" }
    $bad = $manual.Clone(); $bad.Publisher = "Bad`rPublisher"; $bad.Key = 'Note*pad'
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $p @bad }
    if ($r -like 'W32T.PriorInstallInvalid|*' -and $r -match 'Key must be' -and $r -match 'Publisher must be' -and (Get-Hash $p) -ceq $h0) { Ok 'an invalid rule -> W32T.PriorInstallInvalid naming every failed rule (Key and Publisher), nothing written' } else { Bad "invalid: $r" }
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $p @manual -Id 'a', 'b' }
    if ($r -like 'W32T.PriorInstallInvalid|*exactly one*') { Ok '-Id with two values in an add set -> error' } else { Bad "two ids: $r" }
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $p @manual -DisplayNameTemplate 'Notepad++ {v}' }
    if ($r -like 'W32T.PriorInstallInvalid|*not both*') { Ok '-DisplayName with -DisplayNameTemplate -> error' } else { Bad "both names: $r" }
    $noName = $manual.Clone(); $noName.Remove('DisplayName')
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $p @noName }
    if ($r -like 'W32T.PriorInstallInvalid|*DISPLAYNAME waiver*') { Ok 'no name and no DISPLAYNAME waiver -> error' } else { Bad "no name: $r" }
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $p @manual -Mode Enforce }
    if ($r -like 'W32T.PriorInstallInvalid|*needs UninstallerType*' -and $r -match 'needs InstallDir') { Ok 'Enforce without removal data -> W32T.PriorInstallInvalid' } else { Bad "enforce data: $r" }

    # == [4] manual writes ==================================================================================
    Write-Host '[4] Manual writes, D20, Remove, SetMode' -ForegroundColor Cyan
    $before = Get-Cfg $p
    $out = @(Set-Win32ToolkitPriorInstall -ProjectPath $p @manual 6>$null)
    $cfg = Get-Cfg $p
    $e = @($cfg.PriorInstalls.Entries)[0]
    if ($cfg.PriorInstalls.SchemaVersion -eq '1.0' -and $e.Id -eq 'exe-x64' -and $e.Mode -eq 'Block' -and $e.Source -eq 'Operator' -and $e.AddedOn -match '^\d{4}-\d{2}-\d{2}$' -and $out.Count -eq 1 -and $out[0].Proof -eq 'NotNeeded' -and $out[0].Consequence -match 'this install FAILS \(69101\)') { Ok 'Manual Block: the rule written (Id exe-x64, Source Operator, AddedOn); the List object says what a device does' } else { Bad "manual: $($e | ConvertTo-Json -Compress)" }
    # Live row OP-UNPROVEN (round 2): the Block consequence named only the key and the window, as if any install under that key
    # failed; the device leaves another publisher or name, or an older version, as it is (D14) and refuses a newer one (69102).
    if ($out[0].Consequence -ceq 'On devices with HKLM\SOFTWARE\...\Uninstall\Notepad++ (publisher Notepad++ Team, 8.7.9 <= version <= 8.9.8.1) this install FAILS (69101) until the rule is Enforce. A newer one fails the install too (69102); an older or different one is left as it is and the install goes on.') {
        Ok 'the Block consequence names the publisher and what the device leaves alone (another publisher or name, an older version) and refuses (newer)'
    } else { Bad "block consequence: $($out[0].Consequence)" }
    if ((@($cfg.ProcessesToClose) -join ',') -ceq 'notepad++,zeta') { Ok 'D20: notepad++ merged into ProcessesToClose (union, sorted)' } else { Bad "ptc: $(@($cfg.ProcessesToClose) -join ',')" }
    # Live rows OP-BLOCK, RC2-BLOCK, ASSISTED: the D20 line promised "before the removal" for a Block rule, which removes nothing.
    $qb = New-PiProject 'd20block'
    $outB = @(Set-Win32ToolkitPriorInstall -ProjectPath $qb @manual 6>&1 | ForEach-Object { "$_" }) -join "`n"
    $qx = New-PiProject 'd20enforce'
    $outE = @(Set-Win32ToolkitPriorInstall -ProjectPath $qx @manual @enforceArgs -Mode Enforce -Id 'nsis-x64' 6>&1 | ForEach-Object { "$_" }) -join "`n"
    if ($outB -match 'ProcessesToClose gains notepad\+\+: the close-apps dialog closes the app before an Enforce rule removes that install \(a Block rule refuses before the dialog and removes nothing\)\.' -and
        $outE -match 'ProcessesToClose gains notepad\+\+: the close-apps dialog closes the app before the removal\.') { Ok 'D20 line: a Block rule says it removes nothing; an Enforce rule keeps "before the removal"' } else { Bad "d20 text: $outB // $outE" }
    $same = ($before.App | ConvertTo-Json -Compress) -ceq ($cfg.App | ConvertTo-Json -Compress) -and ($before.Installer | ConvertTo-Json -Compress) -ceq ($cfg.Installer | ConvertTo-Json -Compress) -and ($before.OwnIdentity | ConvertTo-Json -Compress -Depth 4) -ceq ($cfg.OwnIdentity | ConvertTo-Json -Compress -Depth 4)
    if ($same) { Ok 'every other AppConfig section unchanged' } else { Bad 'other sections changed' }
    $out = @(Set-Win32ToolkitPriorInstall -ProjectPath $p @manual @enforceArgs -Mode Enforce -Id 'nsis-x64' -Key 'Notepad++ NSIS' 6>&1 | ForEach-Object { "$_" })
    if (($out -join "`n") -match "Prove it: Test-Win32ToolkitProject -ProjectPath '.*' -Scenario Update -Backend HyperV -TestMode Unattended") { Ok "an Enforce rule: the next step 'Prove it: Test-Win32ToolkitProject ... -Scenario Update -Backend HyperV -TestMode Unattended'" } else { Bad "prove hint: $($out -join ' | ')" }
    $cfg = Get-Cfg $p
    if ((@($cfg.PriorInstalls.Entries) | ForEach-Object Id) -join ',' -eq 'exe-x64,nsis-x64') { Ok 'entries sorted by Id' } else { Bad "order: $((@($cfg.PriorInstalls.Entries) | ForEach-Object Id) -join ',')" }
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $p @manual -Id 'dup' }
    if ($r -like 'W32T.PriorInstallInvalid|*same uninstall key*') { Ok 'a second rule for the same key and view -> W32T.PriorInstallInvalid' } else { Bad "dup key: $r" }
    $warn = @(Set-Win32ToolkitPriorInstall -ProjectPath $p -Remove 'exe-x64', 'gone' -Confirm:$false 3>&1 6>$null | Where-Object { $_ -is [Management.Automation.WarningRecord] } | ForEach-Object { "$_" })
    if ($warn.Count -eq 1 -and $warn[0] -like "*'gone'*") { Ok '-Remove warns only for an id that is not there' } else { Bad "remove warnings: $($warn -join ' | ')" }
    $null = Set-Win32ToolkitPriorInstall -ProjectPath $p -Id 'nsis-x64' -Mode Block -Confirm:$false 6>$null
    $cfg = Get-Cfg $p
    $nsis = @($cfg.PriorInstalls.Entries)[0]
    if (@($cfg.PriorInstalls.Entries).Count -eq 1 -and $nsis.Mode -eq 'Block' -and (@($cfg.ProcessesToClose) -join ',') -ceq 'notepad++,zeta') { Ok '-Remove keeps the merged process names; SetMode changes the mode' } else { Bad "remove/setmode: $($cfg | ConvertTo-Json -Depth 5 -Compress)" }
    $raw1 = Get-Content -LiteralPath (Join-Path $p 'SupportFiles\AppConfig.json') -Raw
    $null = Set-Win32ToolkitPriorInstall -ProjectPath $p -Id 'nsis-x64' -Mode Enforce -Confirm:$false 6>$null
    $raw2 = Get-Content -LiteralPath (Join-Path $p 'SupportFiles\AppConfig.json') -Raw
    if ($raw2 -ceq $raw1.Replace('"Mode": "Block"', '"Mode": "Enforce"')) { Ok 'SetMode Block -> Enforce writes nothing but the mode' } else { Bad 'setmode changed more than the mode' }
    # Live rows OP-EXPORT and RC2-PROOF: Enforce again over a proof that still binds said "Prove it:"; a proven rule is named.
    $savedProof = ${function:Get-Win32ToolkitPriorProofState}
    ${function:Get-Win32ToolkitPriorProofState} = { param($ProjectPath) $null = $ProjectPath; [pscustomobject]@{ Id = 'nsis-x64'; Mode = 'Enforce'; Lineage = 'Operator'; State = 'Proven'; Reason = 'proven'; ProvenOn = '2026-10-26'; ProvenVersions = @(); DataLoss = $false; LastFailure = '' } }
    try {
        $null = Set-Win32ToolkitPriorInstall -ProjectPath $p -Id 'nsis-x64' -Mode Block -Confirm:$false 6>$null
        $outP = @(Set-Win32ToolkitPriorInstall -ProjectPath $p -Id 'nsis-x64' -Mode Enforce -Confirm:$false 6>&1 | ForEach-Object { "$_" }) -join "`n"
    }
    finally { ${function:Get-Win32ToolkitPriorProofState} = $savedProof }
    if ($outP -match 'Proven: nsis-x64 \(a Hyper-V Unattended Update test already proved' -and $outP -notmatch 'Prove it:') { Ok 'an Enforce rule that is already proven: "Proven: nsis-x64", no "Prove it:"' } else { Bad "proven hint: $outP" }
    $qm = New-PiProject 'nomode'
    $cfg = Get-Cfg $qm
    $hand = [ordered]@{ Id = 'exe-x64'; Kind = 'ArpKey'; Key = 'Notepad++'; View = 'Native'; Publisher = 'Notepad++ Team'; DisplayName = 'Notepad++ (64-bit x64)'; DisplayNameTemplate = ''; VersionMin = '8.7.9'; VersionMax = '8.9.8.1'; ProcessNames = @('notepad++'); Source = 'Operator'; Track = 'Current'; AddedOn = '2026-10-25' }
    $cfg | Add-Member -NotePropertyName PriorInstalls -NotePropertyValue ([pscustomobject]@{ SchemaVersion = '1.0'; Entries = @([pscustomobject]$hand) }) -Force
    [IO.File]::WriteAllText((Join-Path $qm 'SupportFiles\AppConfig.json'), ($cfg | ConvertTo-Json -Depth 8), $utf8)
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $qm -Id 'exe-x64' -Mode Block -Confirm:$false 6>$null }
    $e = @((Get-Cfg $qm).PriorInstalls.Entries)[0]
    if ($r -eq '' -and $e.Mode -eq 'Block') { Ok 'SetMode on a hand-edited rule without a Mode property sets it (the set is validated as usual)' } else { Bad "no mode: $r" }

    # == [5] FromUpdateTest =================================================================================
    Write-Host '[5] FromUpdateTest' -ForegroundColor Cyan
    function Set-CandidateFile([string]$P, [object[]]$C) {
        $doc = [ordered]@{ SchemaVersion = '1.0'; Baseline = [ordered]@{ Version = '8.8.9'; InstallerType = 'nullsoft' }; Candidates = @($C) }
        [IO.File]::WriteAllText((Join-Path $P 'Documentation\PriorInstallCandidates.json'), ($doc | ConvertTo-Json -Depth 6), $utf8)
    }
    function Cand([hashtable]$O = @{}) { $c = [ordered]@{ ProposedId = 'nsis-x64'; Confidence = 'High'; Key = 'Notepad++'; View = 'Native'; Publisher = 'Notepad++ Team'; DisplayName = 'Notepad++ (64-bit x64)'; DisplayNameTemplate = ''
            ObservedVersion = '8.8.9'; WindowsInstaller = $false; UninstallerType = 'nullsoft'; UninstallerFileName = 'uninstall.exe'; InstallDir = '%ProgramFiles%\Notepad++'; MainExe = 'notepad++.exe'; ProcessNames = @('notepad++') }
        foreach ($k in $O.Keys) { $c[$k] = $O[$k] }; $c }
    $q = New-PiProject 'fut'
    Set-CandidateFile $q @((Cand), (Cand @{ ProposedId = 'exe-x86'; Confidence = 'Low'; Key = 'Other'; View = 'Wow6432'; UninstallerType = ''; InstallDir = ''; MainExe = ''; ProcessNames = @() }))
    $null = Set-Win32ToolkitPriorInstall -ProjectPath $q -FromUpdateTest -Mode Block -Confirm:$false 6>$null
    $e = @((Get-Cfg $q).PriorInstalls.Entries)[0]
    if ($e.Id -eq 'nsis-x64' -and $e.Source -eq 'UpdateTest' -and $e.VersionMin -eq '8.8.9' -and $e.VersionMax -eq '8.9.9' -and $e.Key -eq 'Notepad++') { Ok 'the High candidate: VersionMin = the observed version (exact), VersionMax = the package version (another family), Source UpdateTest' } else { Bad "fut: $($e | ConvertTo-Json -Compress)" }
    # Live row RC2-BLOCK: the same candidate again was refused as 'nsis-x64-2: another entry names the same uninstall key'.
    $hq = Get-Hash $q
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $q -FromUpdateTest -Mode Block -Confirm:$false 6>$null }
    if ($r -like "W32T.PriorInstallInvalid|*is already the Block rule 'nsis-x64': change its mode (Set-Win32ToolkitPriorInstall -ProjectPath '*' -Id nsis-x64 -Mode <mode>)*" -and $r -notmatch 'nsis-x64-2' -and (Get-Hash $q) -ceq $hq) { Ok 'a candidate a rule already names -> W32T.PriorInstallInvalid naming that rule (no made-up id), nothing written' } else { Bad "named candidate: $r" }
    # Live row OP-NEWER (round 2): the replacement was named "(-FromUpdateTest -Id nsis-x64)" - no command, no -Mode (mandatory).
    if ($r -like "*or replace it from this candidate (Set-Win32ToolkitPriorInstall -ProjectPath '$q' -FromUpdateTest -Id nsis-x64 -Mode Block; add -VersionMin / -VersionMax to keep its window)*") { Ok 'the refusal names the full replacement command with the rule''s mode' } else { Bad "replace hint: $r" }
    $null = Set-Win32ToolkitPriorInstall -ProjectPath $q -FromUpdateTest -Mode Report -Id 'nsis-x64' -Confirm:$false 6>$null
    if (@((Get-Cfg $q).PriorInstalls.Entries | Where-Object Id -eq 'nsis-x64')[0].Mode -eq 'Report') { Ok '-FromUpdateTest -Id <that rule> replaces it from the candidate' } else { Bad 'replace by id' }
    $null = Set-Win32ToolkitPriorInstall -ProjectPath $q -FromUpdateTest -Mode Block -Id 'nsis-x64' -Confirm:$false 6>$null
    $null = Set-Win32ToolkitPriorInstall -ProjectPath $q -FromUpdateTest -Mode Report -CandidateKey 'Other' -Confirm:$false 6>$null
    $o = @((Get-Cfg $q).PriorInstalls.Entries | Where-Object Key -eq 'Other')[0]
    if ($o.Id -eq 'exe-x86' -and $o.Mode -eq 'Report' -and $o.View -eq 'Wow6432') { Ok '-CandidateKey picks another candidate' } else { Bad "candidate key: $($o | ConvertTo-Json -Compress)" }
    $qe = New-PiProject 'futexe' -InstallerType 'exe'
    Set-CandidateFile $qe @((Cand))
    $null = Set-Win32ToolkitPriorInstall -ProjectPath $qe -FromUpdateTest -Mode Block -Confirm:$false 6>$null
    $e = @((Get-Cfg $qe).PriorInstalls.Entries)[0]
    if ($e.VersionMax -eq '8.8.9') { Ok 'an EXE package (same family): VersionMax = the observed version (L33)' } else { Bad "own family max: $($e.VersionMax)" }
    $qv = New-PiProject 'futmax' -InstallerType 'exe'
    Set-CandidateFile $qv @((Cand))
    $null = Set-Win32ToolkitPriorInstall -ProjectPath $qv -FromUpdateTest -Mode Block -VersionMax '8.9.0' -VersionMin '8.8' -Confirm:$false 6>$null
    $e = @((Get-Cfg $qv).PriorInstalls.Entries)[0]
    if ($e.VersionMax -eq '8.9.0' -and $e.VersionMin -eq '8.8') { Ok '-VersionMax / -VersionMin override' } else { Bad "override: $($e | ConvertTo-Json -Compress)" }
    $qw = New-PiProject 'futmsi'
    Set-CandidateFile $qw @((Cand @{ WindowsInstaller = $true }))
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $qw -FromUpdateTest -Mode Block -Confirm:$false }
    if ($r -like 'W32T.PriorInstallInvalid|*Windows Installer*') { Ok 'a Windows Installer candidate is never written' } else { Bad "msi cand: $r" }
    $qh = New-PiProject 'futhostile'
    Set-CandidateFile $qh @((Cand @{ DisplayName = "Notepad++`e[2J$([char]0x202E)"; Publisher = "Notepad++ Team" }))
    $out = @(Set-Win32ToolkitPriorInstall -ProjectPath $qh -FromUpdateTest -Mode Report -WhatIf 6>&1 | ForEach-Object { "$_" })
    $joined = $out -join ''
    if (-not $joined.Contains([string][char]0x1B) -and -not $joined.Contains([string][char]0x202E)) { Ok 'hostile candidate strings are neutralised in the preview' } else { Bad 'escape reached the console' }

    # == [6] capture lineage ================================================================================
    Write-Host '[6] capture lineage (rules written by hand)' -ForegroundColor Cyan
    $qc = New-PiProject 'capture'
    $cfg = Get-Cfg $qc
    $cap = [ordered]@{ Id = 'nsis-x64'; Kind = 'ArpKey'; Mode = 'Block'; Key = 'Notepad++'; View = 'Native'; Publisher = 'Notepad++ Team'; DisplayName = 'Notepad++ (64-bit x64)'; DisplayNameTemplate = ''
        VersionMin = '8.7.9'; VersionMax = '8.9.8.1'; UninstallerType = 'nullsoft'; UninstallerFileName = 'uninstall.exe'; UninstallerSigner = ''; InstallDir = '%ProgramFiles%\Notepad++'
        MainExe = 'notepad++.exe'; ProcessNames = @('notepad++'); Source = 'SiblingCapture'; CaptureId = '3f9c0a7d51e2b846'; Track = 'Current'; AddedOn = '2026-10-25' }
    $cfg | Add-Member -NotePropertyName PriorInstalls -NotePropertyValue ([pscustomobject]@{ SchemaVersion = '1.0'; Entries = @([pscustomobject]$cap) }) -Force
    [IO.File]::WriteAllText((Join-Path $qc 'SupportFiles\AppConfig.json'), ($cfg | ConvertTo-Json -Depth 8), $utf8)
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $qc @manual @enforceArgs -Mode Block -Id 'nsis-x64' }
    if ($r -like 'W32T.PriorInstallRefused|*sibling capture*') { Ok 'Manual over a captured rule''s id -> refused' } else { Bad "manual id: $r" }
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $qc @manual @enforceArgs -Mode Block -Id 'other' }
    if ($r -like 'W32T.PriorInstallRefused|*sibling capture*') { Ok 'Manual with a captured rule''s identity (tuple) under another id -> refused' } else { Bad "manual tuple: $r" }
    Set-CandidateFile $qc @((Cand @{ ProposedId = 'nsis-x64' }))
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $qc -FromUpdateTest -Mode Block -Id 'fresh' -Confirm:$false }
    if ($r -like 'W32T.PriorInstallRefused|*') { Ok 'FromUpdateTest over a captured tuple -> refused' } else { Bad "fut tuple: $r" }
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $qc -Waive PROOF -Target 'nsis-x64' -Reason 'pilot' -Confirm:$false }
    if ($r -like 'W32T.PriorInstallRefused|*never allowed*') { Ok '-Waive PROOF on a captured rule -> refused (D59b)' } else { Bad "waive: $r" }
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $qc -Id 'nsis-x64' -Mode Enforce -Confirm:$false }
    if ($r -like "W32T.PriorInstallRefused|*Set-Win32ToolkitPriorInstall -ProjectPath '$qc' -FromSiblingCapture -Mode Enforce -ProposalId nsis-x64*") { Ok 'SetMode Enforce on a captured rule -> refused with the exact -FromSiblingCapture command' } else { Bad "setmode capture: $r" }

    # == [7] decisions ======================================================================================
    Write-Host '[7] decisions' -ForegroundColor Cyan
    $qd = New-PiProject 'decide'
    $null = Set-Win32ToolkitPriorInstall -ProjectPath $qd -Waive DISPLAYNAME -Target 'exe-x64' -Reason 'the vendor writes no name' -Confirm:$false 6>$null
    $null = Set-Win32ToolkitPriorInstall -ProjectPath $qd @noName 6>$null
    $e = @((Get-Cfg $qd).PriorInstalls.Entries)[0]
    if ($e.Id -eq 'exe-x64' -and $e.DisplayName -eq '') { Ok 'a DISPLAYNAME waiver declared before the rule allows an empty name' } else { Bad "waiver first: $($e | ConvertTo-Json -Compress)" }
    $null = Set-Win32ToolkitPriorInstall -ProjectPath $qd -Waive PROOF -Target 'exe-x64' -Reason 'first' -Confirm:$false 6>$null
    $null = Set-Win32ToolkitPriorInstall -ProjectPath $qd -Waive PROOF -Target 'exe-x64' -Reason 'second' -Confirm:$false 6>$null
    $d = @(Get-Win32ToolkitPriorInstallDecision -ProjectPath $qd | Where-Object { $_.Code -eq 'PROOF' })
    if ($d.Count -eq 1 -and $d[0].Reason -eq 'second') { Ok 'one record per Kind + Code + Target: the newer one replaces it' } else { Bad "replace: $($d | ConvertTo-Json -Compress)" }
    $null = Set-Win32ToolkitPriorInstallDecision -ProjectPath $qd -Record @{ Kind = 'Approval'; Code = 'SIBLING-ENFORCE'; Target = 'exe-x64'; ProposalId = 'exe-x64'; ProposalHash = ('A' * 64); CaptureIds = @(); On = '2026-10-25'; Demoted = '' } -Confirm:$false
    $null = Set-Win32ToolkitPriorInstall -ProjectPath $qd -Revoke PROOF -Target 'exe-x64' -Confirm:$false 6>$null
    $d = @(Get-Win32ToolkitPriorInstallDecision -ProjectPath $qd)
    if (@($d | Where-Object Code -eq 'PROOF').Count -eq 0 -and @($d | Where-Object Kind -eq 'Approval').Count -eq 1) { Ok '-Revoke removes the waiver; an Approval stays (it cannot be revoked)' } else { Bad "revoke: $($d | ConvertTo-Json -Compress)" }
    $bytes = [IO.File]::ReadAllBytes((Join-Path $qd 'Documentation\PriorInstallDecisions.json'))
    if (-not ($bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB) -and -not (Test-Path -LiteralPath (Join-Path $qd 'Documentation\PriorInstallDecisions.json.tmp'))) { Ok 'the decisions file is BOM-less, written through a .tmp file' } else { Bad 'decisions file' }
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $qd -Acknowledge DATA-LOSS -Target 'BAD ID' -Reason 'x' -Confirm:$false }
    if ($r -like 'W32T.PriorInstallInvalid|*') { Ok 'a decision for an invalid target id -> W32T.PriorInstallInvalid' } else { Bad "bad target: $r" }

    # == [8] FromSiblingCapture =============================================================================
    Write-Host '[8] FromSiblingCapture (installer-identity PR 3b, A1)' -ForegroundColor Cyan
    . (Join-Path $repo 'Tests\Fixtures\sibling-proposal\SiblingFixture.ps1')
    function Get-AuthenticodeSignature { [CmdletBinding()] param([string]$LiteralPath) $null = $LiteralPath; [pscustomobject]@{ Status = 'Valid'; SignerCertificate = [pscustomobject]@{ Subject = $script:TestSiblingSigner } } }
    function New-SibProject([string]$Name) {
        $sp = New-PiProject $Name
        [IO.File]::WriteAllBytes((Join-Path $sp 'Files\npp.msi'), [byte[]](1, 2, 3))
        $innoArgs = @{ Type = 'inno'; Key = 'Notepad++ Inno_is1'; InnoMarkers = $true; ProductCodes = @('Notepad++ Inno_is1'); DisplayName = 'Notepad++ Inno'; Dir = 'Notepad++ Inno'; Main = 'npp.exe'; Uninstaller = 'unins000.exe'; DefaultInstallLocation = '' }
        $flagArgs = @{ NoNsis = $true; Key = 'NppPortable'; View = 'Wow6432'; ProductCodes = @('NppPortable'); DisplayName = 'Npp Portable'; Dir = 'NppPortable'; Main = 'npp.exe'; DefaultInstallLocation = '' }
        foreach ($set in @(@{}, $innoArgs, $flagArgs)) {
            foreach ($v in @(@{ Version = '8.7.9'; Role = 'Floor' }, @{ Version = '8.9.8'; Role = 'Newest' })) {
                $all = $set.Clone(); foreach ($k in $v.Keys) { $all[$k] = $v[$k] }
                $null = Write-TestSiblingRecord -ProjectPath $sp -Record (New-TestSiblingRecord @all)
            }
        }
        $sp
    }
    $ps = New-SibProject 'sibling'
    $h = Get-Hash $ps
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $ps -FromSiblingCapture -Mode Enforce -Confirm:$false }
    if ($r -like 'W32T.PriorInstallRefused|*only by name*-ProposalId*' -and (Get-Hash $ps) -ceq $h) { Ok 'Enforce from a capture without -ProposalId -> W32T.PriorInstallRefused, nothing written' } else { Bad "enforce no id: $r" }
    $listOut = @(Set-Win32ToolkitPriorInstall -ProjectPath $ps 6>&1 | ForEach-Object { "$_" }) -join "`n"
    if ($listOut -match 'nsis-x64 +Notepad\+\+ \[Native\] nullsoft 8\.7\.9\.0 <= version <= 8\.9\.8\.0; High, Current, Enforce-eligible; not applied' -and $listOut -match 'exe-x86 .*Block only; not applied; flags GenericExe') { Ok 'List shows the proposals (window, confidence, eligibility, applied or not, flags)' } else { Bad "list: $listOut" }
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $ps -FromSiblingCapture -Mode Enforce -ProposalId 'exe-x86' -Confirm:$false }
    if ($r -like 'W32T.PriorInstallRefused|*Not eligible for Enforce*exe-x86: GenericExe*' -and (Get-Hash $ps) -ceq $h) { Ok 'an ineligible proposal (GenericExe) as Enforce -> refused and listed, nothing written' } else { Bad "ineligible: $r" }
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $ps -FromSiblingCapture -Mode Block -ProposalId 'nope' -Confirm:$false }
    if ($r -like "W32T.PriorInstallInvalid|*No sibling-capture proposal 'nope'*nsis-x64*") { Ok 'an unknown -ProposalId -> W32T.PriorInstallInvalid naming the proposals' } else { Bad "unknown id: $r" }
    $tr = Join-Path $root 'whatif.txt'
    $null = Start-Transcript -LiteralPath $tr -Force
    $null = Set-Win32ToolkitPriorInstall -ProjectPath $ps -FromSiblingCapture -Mode Enforce -ProposalId 'nsis-x64', 'inno-x64' -WhatIf 6>$null
    $null = Stop-Transcript
    $whatIf = @(Get-Content -LiteralPath $tr | Where-Object { $_ -match '^What if: .*from the sibling-capture proposal' })
    if ($whatIf.Count -eq 2 -and (Get-Hash $ps) -ceq $h) { Ok 'two proposals -> two confirmations (-WhatIf: two What if lines), nothing written' } else { Bad "whatif count: $($whatIf.Count)" }
    $null = Set-Win32ToolkitPriorInstall -ProjectPath $ps -FromSiblingCapture -Mode Enforce -ProposalId 'nsis-x64', 'inno-x64' -Confirm:$false 6>$null
    $cfg = Get-Cfg $ps
    $sib = ConvertTo-Win32ToolkitSiblingProposal -ProjectPath $ps
    $pn = @($sib.Proposals | Where-Object ProposalId -ceq 'nsis-x64')[0]; $pi = @($sib.Proposals | Where-Object ProposalId -ceq 'inno-x64')[0]
    $en = @($cfg.PriorInstalls.Entries | Where-Object Id -ceq 'nsis-x64')[0]; $ei = @($cfg.PriorInstalls.Entries | Where-Object Id -ceq 'inno-x64')[0]
    if (@($cfg.PriorInstalls.Entries).Count -eq 2 -and $en.Mode -eq 'Enforce' -and $en.Source -eq 'SiblingCapture' -and $en.CaptureId -ceq $pn.FloorCaptureId -and $en.VersionMin -eq '8.7.9.0' -and $en.VersionMax -eq '8.9.8.0' -and $en.Track -eq 'Current' -and $ei.UninstallerType -eq 'inno' -and
        (Get-Win32ToolkitPriorInstallHash -Kind Tuple -Entry $en) -ceq $pn.ProposalHash) {
        Ok 'the two rules written: Source SiblingCapture, CaptureId = the floor record, the window from the records (8.7.9.0..8.9.8.0), the proposal''s identity'
    } else { Bad "written: $($cfg.PriorInstalls | ConvertTo-Json -Depth 5 -Compress)" }
    $ap = @(Get-Win32ToolkitPriorInstallDecision -ProjectPath $ps | Where-Object Kind -eq 'Approval')
    if ($ap.Count -eq 2 -and @($ap | Where-Object { $_.Target -ceq 'nsis-x64' -and $_.ProposalId -ceq 'nsis-x64' -and $_.ProposalHash -ceq $pn.ProposalHash -and (@($_.CaptureIds) -join ',') -ceq (@($pn.CaptureIds) -join ',') -and $_.Latest }).Count -eq 1 -and @($ap | Where-Object { $_.Target -ceq 'inno-x64' -and $_.ProposalHash -ceq $pi.ProposalHash }).Count -eq 1) {
        Ok 'one Approval per proposal (ProposalId, ProposalHash = the Tuple, CaptureIds floor first)'
    } else { Bad "approvals: $($ap | ConvertTo-Json -Compress)" }
    if ((@($cfg.ProcessesToClose) -join ',') -ceq 'notepad++,npp,zeta') { Ok 'D20: the process names of the captured rules merged into ProcessesToClose' } else { Bad "ptc: $(@($cfg.ProcessesToClose) -join ',')" }

    # Installer-identity PR 3 live checks: a Windows Sandbox record keeps its identity Block-only, so the refusal never
    # says "capture again" for it and the Block consequence never says "until the rule is Enforce" (SB-CAPTURE, ASSISTED);
    # the probe's data loss is said in the List and the preview, not first at Export (GOAL-APPROVE).
    $psb = New-PiProject 'sandbox-tainted'
    [IO.File]::WriteAllBytes((Join-Path $psb 'Files\npp.msi'), [byte[]](1, 2, 3))
    foreach ($v in @(@{ Version = '8.7.9'; Role = 'Floor' }, @{ Version = '8.9.8'; Role = 'Newest'; Backend = 'Sandbox' })) { $null = Write-TestSiblingRecord -ProjectPath $psb -Record (New-TestSiblingRecord @v) }
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $psb -FromSiblingCapture -Mode Enforce -ProposalId 'nsis-x64' -Confirm:$false }
    if ($r -like 'W32T.PriorInstallRefused|*Not eligible for Enforce*' -and $r -match 'these reasons come from capture records of that identity and stay with it \(a later capture does not take them back\)\.$' -and $r -notmatch 'capture again') { Ok 'a Sandbox-flagged proposal as Enforce -> refused without "capture again" (the identity stays Block-only)' } else { Bad "sandbox refusal: $r" }
    $out = try { @(Set-Win32ToolkitPriorInstall -ProjectPath $psb -FromSiblingCapture -Mode Block -ProposalId 'nsis-x64' -Confirm:$false 6>&1 | ForEach-Object { "$_" }) -join "`n" } catch { "THREW: $($_.Exception.Message)" }
    if ($out -match 'Device consequence  : On devices with .* this install FAILS \(69101\); this identity stays Block-only' -and $out -notmatch 'until the rule is Enforce') { Ok 'the Block preview of a Sandbox-flagged identity says it stays Block-only (no "until the rule is Enforce")' } else { Bad "sandbox block preview: $out" }
    # Live row ASSISTED (round 2): a Block-only identity's List line and Block preview asked for the Enforce-only DATA-LOSS
    # acknowledgement although such a rule never removes anything.
    $psd = New-PiProject 'sandbox-dataloss'
    [IO.File]::WriteAllBytes((Join-Path $psd 'Files\npp.msi'), [byte[]](1, 2, 3))
    foreach ($v in @(@{ Version = '8.7.9'; Role = 'Floor'; RootConfigRemoved = $true }, @{ Version = '8.9.8'; Role = 'Newest'; Backend = 'Sandbox' })) { $null = Write-TestSiblingRecord -ProjectPath $psd -Record (New-TestSiblingRecord @v) }
    $listSd = @(Set-Win32ToolkitPriorInstall -ProjectPath $psd 6>&1 | ForEach-Object { "$_" }) -join "`n"
    $prevSd = @(Set-Win32ToolkitPriorInstall -ProjectPath $psd -FromSiblingCapture -Mode Block -ProposalId 'nsis-x64' -WhatIf 6>&1 | ForEach-Object { "$_" }) -join "`n"
    if ($listSd -match 'nsis-x64 .*Block only' -and $listSd -notmatch 'data loss|DATA-LOSS' -and $prevSd -match 'Device consequence' -and $prevSd -notmatch 'Data loss|DATA-LOSS') { Ok 'a Block-only identity with the probe''s data loss: no Enforce-only DATA-LOSS line in the List or the Block preview' } else { Bad "block-only data loss: list=$listSd preview=$prevSd" }
    $pdl = New-PiProject 'dataloss'
    [IO.File]::WriteAllBytes((Join-Path $pdl 'Files\npp.msi'), [byte[]](1, 2, 3))
    foreach ($v in @(@{ Version = '8.7.9'; Role = 'Floor'; RootConfigRemoved = $true }, @{ Version = '8.9.8'; Role = 'Newest' })) { $null = Write-TestSiblingRecord -ProjectPath $pdl -Record (New-TestSiblingRecord @v) }
    $listDl = @(Set-Win32ToolkitPriorInstall -ProjectPath $pdl 6>&1 | ForEach-Object { "$_" }) -join "`n"
    $prevDl = @(Set-Win32ToolkitPriorInstall -ProjectPath $pdl -FromSiblingCapture -Mode Enforce -ProposalId 'nsis-x64' -WhatIf 6>&1 | ForEach-Object { "$_" }) -join "`n"
    if ($listDl -match 'nsis-x64 .*; data loss \(its uninstaller deletes configuration in its folder: Enforce needs -Acknowledge DATA-LOSS\)' -and $prevDl -match 'Data loss +: the removability probe saw its uninstaller delete configuration in its install folder') { Ok 'a proposal with the probe''s data loss: the List and the Enforce preview say so (before the approval)' } else { Bad "data loss: list=$listDl preview=$prevDl" }
    # Live row GOAL-APPROVE: after the Enforce approval only the proof was named as the next step; Export also needed the
    # DATA-LOSS acknowledgement. GOAL-EXPORT: once acknowledged, the List still asked for it.
    $appDl = @(Set-Win32ToolkitPriorInstall -ProjectPath $pdl -FromSiblingCapture -Mode Enforce -ProposalId 'nsis-x64' -Confirm:$false 6>&1 | ForEach-Object { "$_" }) -join "`n"
    if ($appDl -match 'Prove it: Test-Win32ToolkitProject' -and $appDl -match "Export also needs the data-loss acknowledgement .*: Set-Win32ToolkitPriorInstall -ProjectPath '.*' -Acknowledge DATA-LOSS -Target nsis-x64 -Reason '<why>'") { Ok 'Enforce approval of a proposal with data loss: the next steps name the proof AND the DATA-LOSS acknowledgement' } else { Bad "next steps: $appDl" }
    $null = Set-Win32ToolkitPriorInstall -ProjectPath $pdl -Acknowledge DATA-LOSS -Target 'nsis-x64' -Reason 'settings live in %APPDATA%' -Confirm:$false 6>$null
    $listAck = @(Set-Win32ToolkitPriorInstall -ProjectPath $pdl 6>&1 | ForEach-Object { "$_" }) -join "`n"
    if ($listAck -match 'nsis-x64 .*; data loss \(its uninstaller deletes configuration in its folder; acknowledged\)' -and $listAck -notmatch 'Enforce needs -Acknowledge DATA-LOSS') { Ok 'after the acknowledgement the List says "acknowledged" instead of asking for it' } else { Bad "ack list: $listAck" }

    # the bulk form never touches an existing rule (B27)
    $pb = New-SibProject 'bulk'
    $null = Set-Win32ToolkitPriorInstall -ProjectPath $pb -FromSiblingCapture -Mode Enforce -ProposalId 'nsis-x64' -Confirm:$false 6>$null
    $before = (Get-Cfg $pb).PriorInstalls.Entries | Where-Object Id -ceq 'nsis-x64' | ConvertTo-Json -Compress
    $ap0 = @(Get-Win32ToolkitPriorInstallDecision -ProjectPath $pb | Where-Object Kind -eq 'Approval').Count
    $out = @(Set-Win32ToolkitPriorInstall -ProjectPath $pb -FromSiblingCapture -Mode Block -Confirm:$false 6>&1 | ForEach-Object { "$_" }) -join "`n"
    $cfg = Get-Cfg $pb
    $ids = (@($cfg.PriorInstalls.Entries) | ForEach-Object { "$($_.Id)=$($_.Mode)" }) -join ','
    $after = $cfg.PriorInstalls.Entries | Where-Object Id -ceq 'nsis-x64' | ConvertTo-Json -Compress
    if ($ids -ceq 'inno-x64=Block,nsis-x64=Enforce' -and $after -ceq $before -and @(Get-Win32ToolkitPriorInstallDecision -ProjectPath $pb | Where-Object Kind -eq 'Approval').Count -eq $ap0 -and $out -match 'not applied: nsis-x64 .*already a rule' -and $out -match 'not applied: exe-x86 .*flags: GenericExe') {
        Ok 'bulk Block: only the High flag-free proposal that is not a rule yet (inno-x64); the existing Enforce rule unchanged; the flagged one listed, never written; no approval'
    } else { Bad "bulk: $ids / $out" }

    # SetMode Enforce on a captured rule whose id is not its proposal's: the command names the proposal (by identity)
    $pn = New-SibProject 'renamed'
    $null = Set-Win32ToolkitPriorInstall -ProjectPath $pn -FromSiblingCapture -Mode Block -ProposalId 'nsis-x64' -Confirm:$false 6>$null
    $cfg = Get-Cfg $pn
    $cfg.PriorInstalls.Entries[0].Id = 'npp-nsis'
    [IO.File]::WriteAllText((Join-Path $pn 'SupportFiles\AppConfig.json'), ($cfg | ConvertTo-Json -Depth 8), $utf8)
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $pn -Id 'npp-nsis' -Mode Enforce -Confirm:$false }
    if ($r -like "W32T.PriorInstallRefused|*-FromSiblingCapture -Mode Enforce -ProposalId nsis-x64*" -and $r -notlike '*-ProposalId npp-nsis*') { Ok "SetMode Enforce on the captured rule 'npp-nsis' -> refused; the command names its proposal 'nsis-x64'" } else { Bad "setmode proposal id: $r" }

    # a relabel: the operator types a proposal's identity by hand
    $pr = New-SibProject 'relabel'
    $hr = Get-Hash $pr
    $r = Get-Thrown { Set-Win32ToolkitPriorInstall -ProjectPath $pr @manual @enforceArgs -Mode Block -Id 'mine' -UninstallerSigner $script:TestSiblingSigner }
    if ($r -like "W32T.PriorInstallRefused|*is the sibling-capture proposal 'nsis-x64'*-FromSiblingCapture*" -and (Get-Hash $pr) -ceq $hr) { Ok 'a Manual rule with a current proposal''s identity (a relabel) -> refused with the -FromSiblingCapture command, nothing written' } else { Bad "relabel: $r" }
    Remove-Item Function:\Get-AuthenticodeSignature
}
finally {
    Remove-Item -LiteralPath $root -Recurse -Force -ErrorAction SilentlyContinue
}

Write-Host ''
if ($fail -eq 0) { Write-Host 'All PriorInstall tests passed.' -ForegroundColor Green; exit 0 }
else { Write-Host "$fail PriorInstall test(s) FAILED." -ForegroundColor Red; exit 1 }
